# ---------------------------------------------------------------------------
# Tool schema registry and parameter validation
# ---------------------------------------------------------------------------

def _validate_and_fix_tool_input(tool_name: str, input_dict: dict[str, Any], source_body: dict[str, Any] | None = None) -> dict[str, Any]:
    dialect = TOOL_DIALECTS.create(
        "claude",
        repair=lambda name, value: _tool_schema_validate_and_fix(name, value, source_body, log=router_log),
    )
    return dict(dialect.repair_tool_input(tool_name, input_dict))
def should_drop_emitted_tool_call(tool_name: str, tool_input: dict[str, Any], raw_name: str = "", source_body: dict[str, Any] | None = None, supplied_input: dict[str, Any] | None = None) -> bool:
    # Judge completeness against what the model actually emitted. `tool_input`
    # has already been through _validate_and_fix_tool_input, which injects a
    # typed empty value for every absent required field, so checking it here
    # would only ever re-detect the repair layer's own placeholders.
    missing = _missing_required_tool_fields(tool_name, tool_input if supplied_input is None else supplied_input, source_body)
    if not missing:
        return False
    router_log(
        "WARN",
        f"dropped emitted tool call with missing required fields raw_name={raw_name or tool_name!r} "
        f"matched_name={tool_name!r} fields={','.join(missing)}",
    )
    append_tool_call_log(
        "dropped_tool_call_missing_required",
        {
            "raw_name": raw_name or tool_name,
            "matched_name": tool_name,
            "missing_required": missing,
            "emitted_input": tool_input,
        },
    )
    return True

def side_effect_tool_call_dedupe_key(tool_name: str, tool_input: dict[str, Any]) -> str | None: return tool_side_effect_dedupe_service().key(tool_name, tool_input)
def should_drop_duplicate_side_effect_tool_call(tool_name: str, tool_input: dict[str, Any], raw_name: str = "", source_body: dict[str, Any] | None = None) -> bool: return tool_side_effect_dedupe_service().should_drop(tool_name, tool_input, raw_name, source_body)

def tool_side_effect_dedupe_service() -> ToolSideEffectDedupeService:
    return ToolSideEffectDedupeService(
        policy=ToolSideEffectDedupePolicy(
            frozenset({"send_message", "send_dm", "send_file", "create_message", "create_dm", "post_message", "reply"}),
            ttl_seconds=_TOOL_SIDE_EFFECT_DEDUP_TTL_SECONDS,
        ),
        repository=ToolSideEffectDedupeRepository(
            _TOOL_SIDE_EFFECT_DEDUP_RECENT,
            _TOOL_SIDE_EFFECT_DEDUP_LOCK,
        ),
        ports=ToolSideEffectDedupePorts(time.monotonic, append_tool_call_log, router_log),
    )

