def run_external_menu(name: str) -> int | None:
    if os.name == "nt":
        return None
    exe = find_executable(name)
    if not exe:
        return None
    return subprocess.call([exe])

def has_noninteractive_claude_args(passthrough: list[str]) -> bool: return any((arg == '-p' or arg == '--print' or arg.startswith('--print=') for arg in passthrough))

def run_prelaunch_menu(passthrough: list[str], skip_menu: bool = False, force_menu: bool = False) -> int:
    if not force_menu and (
        skip_menu or has_noninteractive_claude_args(passthrough) or os.environ.get("CIEL_RUNTIME_SKIP_MENU") == "1"
    ):
        return 0
    if not (sys.stdin.isatty() and sys.stdout.isatty()):
        return 0
    if os.environ.get("CIEL_RUNTIME_USE_LEGACY_MENU") == "1":
        rc = run_external_menu("ciel-runtime-menu")
        if rc is not None:
            return rc
    result = portable_prelaunch_menu(passthrough)
    if result == PRELAUNCH_RELOAD:
        subprocess.call([sys.executable, *sys.argv])
        return PRELAUNCH_CANCEL
    return result

def start_router_if_needed(*, replace_active_clients: bool = False) -> bool:
    """Start or reuse the shared router without killing another live client.

    Replacing active clients is an explicit maintenance operation.  A normal
    Claude launch can share a matching router, and must not SIGTERM an existing
    ciel-runtime wrapper (and its Claude Code child) merely because another
    launch happens in the same user account.
    """
    return start_project_router_if_needed(
        replace_active_clients=replace_active_clients,
        config=router_process_config(),
        identity=RouterStartupIdentity(version=VERSION, source_fingerprint=SOURCE_FINGERPRINT),
        state=RouterStartupStatePorts(health=router_health, active_client_pids=active_router_client_pids,
                                      health_matches_current=router_health_matches_current, health_config_matches_current=router_health_config_matches_current,
                                      terminate_active_clients=terminate_active_router_clients, ensure_port_available=ensure_router_port_available_for_spawn,
                                      reuse_enabled=lambda: env_bool(os.environ.get("CIEL_RUNTIME_REUSE_ROUTER"), False), log=router_log),
        spawn=RouterSpawnPorts(popen=subprocess.Popen, router_up=router_up, now=time.time, sleep=time.sleep,
                               process_id=os.getpid, environment=os.environ.copy),
        executable=sys.executable,
        entrypoint=Path(__file__).resolve(),
        log_path=LOG_PATH,
        platform_name=os.name,
    )

def should_attach_web_search(provider: str, cfg: dict[str, Any], override: bool | None) -> bool:
    if override is not None:
        return override
    pcfg = cfg.get("providers", {}).get(provider, {}) if isinstance(cfg.get("providers"), dict) else {}
    contract = provider_contract_config(provider, pcfg)
    return PROVIDER_COMPATIBILITY.resolve(provider).auto_web_search(contract) and bool(
        cfg.get("web_search", {}).get("auto_for_non_native", True)
    )

def should_append_compat_prompt(provider: str, pcfg: dict[str, Any], cfg: dict[str, Any]) -> bool: return PROVIDER_COMPATIBILITY.resolve(provider).requires_compat_prompt and bool(cfg.get('claude_code', {}).get('compat_prompt_for_non_anthropic', True))
