        provider_commands=cli_dispatch.CliProviderCommands(cmd_advisor_model, cmd_api_key, cmd_base_url, cmd_language, cmd_log_level, cmd_model,
                                                           cmd_models, cmd_provider, cmd_provider_options, cmd_set_api_key),
